import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] probabilities = new double[n];
        for (int i = 0; i < n; i++) {
            probabilities[i] = sc.nextDouble();
        }

        double[] result = new double[n];
        double[] dynamic = new double[1 << n];
        double[] sum_mask = new double[1 << n];

        // Function to count set bits in an integer
        // Using built-in Java function Integer.bitCount
        // No need for lambda

        for (int mask = 0; mask < (1 << n); mask++) {
            double s = 0.0;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    s += probabilities[i];
                }
            }
            sum_mask[mask] = s;
        }

        dynamic[0] = 1.0;
        int flag = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            int count_bits_mask = Integer.bitCount(mask);
            if (count_bits_mask > k) continue;
            if (dynamic[mask] < 1e-100) continue;
            if (count_bits_mask == k) flag = 1;
            double remaining_sum = 1.0 - sum_mask[mask];
            if (remaining_sum < 1e-6) continue;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) continue;
                double prob_move = dynamic[mask] * probabilities[i] / remaining_sum;
                int next_mask = mask | (1 << i);
                dynamic[next_mask] += prob_move;
            }
        }

        if (flag == 0) {
            for (int i = 0; i < n; i++) {
                result[i] = (probabilities[i] < 1e-6) ? 0.0 : 1.0;
            }
        } else {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (Integer.bitCount(mask) == k) {
                    for (int i = 0; i < n; i++) {
                        if (((mask >> i) & 1) == 1) {
                            result[i] += dynamic[mask];
                        }
                    }
                }
            }
        }

        System.out.printf("%.12f", result[0]);
        for (int i = 1; i < n; i++) {
            System.out.print(" ");
            System.out.printf("%.12f", result[i]);
        }
        System.out.println();
        sc.close();
    }
}
